window.StrictDoc.search.nodesByMid = {"1":{"MID":"d6ac6ab5c5aa44c7b873231a5eaf6919","UID":"BENCH-001","TITLE":"Provenance","STATEMENT":"Download a public-domain network corpus and retain its SHA-256 and source URL. Use deterministic ASCII/LF derivatives of approximately 1, 8 and 32 MiB.\n","COMMENT":"Program.Main; results/environment.json; source.txt; https://www.gutenberg.org/cache/epub/2600/pg2600.txt","_LINK":"BENCH-001"},"2":{"MID":"76b1b9d396714b9db67e77f0ce0576dd","UID":"BENCH-002","TITLE":"Equivalent implementations","STATEMENT":"Compare eight documented operations using GNU utilities, idiomatic PowerShell pipelines and PowerShell StreamReader loops. Validate output length and SHA-256 against an independent reference for every run.\n","COMMENT":"Program.Oracle, Program.Run, worker.ps1, Supplement.cs, select-string.ps1; results/validation.json; results/select-string-validation.json; results/runs.jsonl; results/select-string-runs.jsonl","_LINK":"BENCH-002"},"3":{"MID":"e0a64706070d47c8821a0024e147ad10","UID":"BENCH-003","TITLE":"Repeatable timing","STATEMENT":"Run sequentially with one warmup and seven measured repeats per cell, seeded random order and process-startup-inclusive wall time. Retain raw measurements and report medians and dispersion.\n","COMMENT":"Program.Main, Program.Run; results/runs.jsonl; results/report.html","_LINK":"BENCH-003"},"4":{"MID":"0bb3d823d42d46c4b127e35fe2199074","UID":"BENCH-004","TITLE":"Verification evidence","STATEMENT":"Run edge cases, reproducible randomized equivalence checks, negative cases and deliberate worker mutations. Collect line and branch coverage where tooling supports it and disclose gaps.\n","COMMENT":"Program.Test; results/validation.json; results/coverage-tests.cobertura.xml; README.md","_LINK":"BENCH-004"},"5":{"MID":"dd9ee112c3c3432f97478864da625d08","UID":"BENCH-005","TITLE":"Installed ripgrep comparison","STATEMENT":"Install BurntSushi.ripgrep.MSVC with winget. Compare four equivalent search operations against contemporaneous GNU grep, interleaving sequential runs across all three existing inputs with one warmup and seven measured repetitions. Record the installed executable version, path and SHA-256, verify outputs, and retain seeded fuzz, negative, mutation and coverage evidence.\n","COMMENT":"RipgrepBench.cs; results/ripgrep-environment.json; results/ripgrep-runs.jsonl; results/ripgrep-validation.json; results/coverage-ripgrep.cobertura.xml; Analyze.cs; results/report.html","_LINK":"BENCH-005"},"6":{"MID":"273e4cd1609b4cb99fc61ff951d9352d","UID":"BENCH-006","TITLE":"Small-file latency","STATEMENT":"Compare literal search, regex search and matching-line counts on contiguous corpus slices near 1 KiB and 64 KiB using ripgrep, GNU grep, PowerShell pipeline, PowerShell reader and Select-String. Interleave all five engines, include process startup, verify every output, and retain seven measured repetitions plus one warmup per cell. Verify fixed and seeded randomized fixtures and record input provenance, match counts and coverage limitations.\n","COMMENT":"RipgrepBench.Small, RipgrepBench.Run, RipgrepBench.Oracle; results/small-runs.jsonl; results/small-environment.json; results/small-validation.json; results/coverage-ripgrep.cobertura.xml; Analyze.cs; results/report.html","_LINK":"BENCH-006"},"7":{"MID":"04674cea7d3842ad890d542b2d6fe9ea","UID":"BENCH-007","TITLE":"Both rawk implementations","STATEMENT":"Build stefanalfbo/rawk and quinnjr/rawk (awk-rs) from unmodified pinned commits in release mode with locked dependencies. Compare identical field extraction, word count and line count programs against contemporaneous GNU awk at all five existing file sizes, with sequential interleaved order, one warmup and seven measured repetitions. Verify each output against an independent reference; retain compiler, source and executable provenance, bounded fuzz, malformed-input, negative, mutation and coverage evidence.\n","COMMENT":"RawkBench.Main, RawkBench.Run, RawkBench.Oracle, RawkBench.Validate; results/rawk-environment.json; results/rawk-runs.jsonl; results/rawk-validation.json; results/coverage-rawk.cobertura.xml; Analyze.cs; results/report.html","_LINK":"BENCH-007"},"8":{"MID":"9c1ee75dd84841deacb150864a814c11","UID":"BENCH-008","TITLE":"Long-field scanner correctness","STATEMENT":"Retain the original frawk long-field compatibility failure. Diagnose buffer-growth state handling, provide a separate minimal source fix, and verify boundary and seeded randomized cases against independent expected output. Record targeted test, negative-control and coverage evidence; patched results must not silently replace historical benchmark results.\n","COMMENT":"tools/variants/frawk-longline/src/runtime/splitter/chunk.rs; tools/variants/frawk-longline/src/runtime/splitter/batch.rs; scripts/FrawkProbe.cs; scripts/FrawkRegression.cs; results/patches/frawk-longline.patch; results/frawk-bug/frawk-long-field-fix.patch; results/frawk-bug/patch-application.json; results/frawk-bug/README.md; results/frawk-bug/coverage/summary.json","_LINK":"BENCH-008"},"9":{"MID":"2f004ee271954e44a2d2194a34b56fb4","UID":"BENCH-009","TITLE":"Tuned GNU tools as user defaults","STATEMENT":"Build GNU awk with -O3 -march=native -mtune=native -ftree-vectorize. Retain compiler flags and upstream test logs. Install the tuned GNU awk and grep in a separate user directory with their runtime dependencies. Verify deterministic long-field and randomized outputs against existing GNU references, reject malformed programs, and detect a deliberate output mutation before prepending the installation directory to the user PATH. Preserve the previous user PATH for rollback and disclose test coverage limitations.\n","COMMENT":"scripts/build-awk.sh; scripts/VerifyTunedTools.cs; scripts/InstallTunedTools.ps1; results/awk-tuned/flags.txt; results/awk-tuned/check.log; results/awk-tuned/installation-verification.txt; results/awk-tuned/installed-hashes.json","_LINK":"BENCH-009"},"10":{"MID":"16c566de24c2480da76d088834c8661d","UID":"BENCH-010","TITLE":"Sed implementations and replacement alternatives","STATEMENT":"Compare GNU sed, BusyBox sed, uutils/sed and red on six equivalent operations across the existing five corpus sizes. Compare sd only for literal and numeric-regex replacements using non-mutating preview mode. Deduplicate byte-identical GNU binaries. Qualify each corpus cell, use one warmup and seven seeded shuffled sequential repeats, verify every timed output by length and SHA-256, and preserve input hashes. Retain edge/binary compatibility failures separately from passes. Record pinned acquisitions, independent oracle tests, seeded random cases, malformed input, command and Stryker.NET source mutations, line/branch coverage and tooling limitations. Add results to the existing report without combining historical sessions.\n","COMMENT":"SedBench.cs; SedSemantics.cs; SedBench.Tests/UnitTest1.cs; SedBench.Tests/stryker-config.json; scripts/Get-SedTools.ps1; scripts/Get-SedTools.Tests.ps1; scripts/sed-dependencies.json; results/sed/environment.json; results/sed/runs.jsonl; results/sed/validation.json; results/sed/verification-summary.json; results/sed/README.md; Analyze.cs; results/report.html","_LINK":"BENCH-010"},"11":{"MID":"37c5f4c703f24a5d9010b90fa30c9085","UID":"BENCH-011","TITLE":"Offline experimental overview","STATEMENT":"Generate a self-contained responsive HTML overview of the methodology, nine experimental cohorts, findings, verification failures and limitations. Embed all 427 seven-repeat summaries (2,989 measured commands and 427 warmups). Restrict interactive rankings to original cohorts, show median/quartiles/observed ranges, and avoid throughput claims for early-exit workloads. Validate data completeness and units, malformed input, deterministic native/managed generation, seeded properties and source/client mutations. Record coverage scopes and disclose the lack of rendered visual verification when browser policy prevents preview. Retain generator/template sources and publish the overview with the existing repository.\n","COMMENT":"Overview.cs; OverviewModel.cs; Overview.template.html; Directory.Build.props; SedBench.Tests/OverviewTests.cs; SedBench.Tests/overview-stryker-config.json; scripts/Build-Overview.ps1; scripts/Test-OverviewDom.cjs; scripts/overview-dom-package.json; scripts/overview-dom-lock.yaml; results/overview.html; results/overview-verification/README.md; results/overview-verification/determinism.json","_LINK":"BENCH-011"},"12":{"MID":"866cedb34af2468d8443815e64a33e8c","UID":"BENCH-012","TITLE":"Diff implementations, algorithms and compiler tuning","STATEMENT":"Compare GNU diff default/minimal/speed-large-files, same-source generic/native GNU and Rust uutils builds, official uutils, BusyBox and Git Myers/minimal/patience/histogram. Use deterministic book and source-code fixtures with identical, scattered, inserted/deleted, moved, repetitive, different and long-line content. Record actual byte sizes and hashes. Qualify each cell by applying its unified patch independently and comparing reconstructed bytes exactly; repeat verification for every timed sample. Retain edge/binary failures and timeout exclusions separately. Run sequential shuffled fresh processes with one warmup and seven measured repetitions, recording wall time, CPU time, process peak working set and patch/edit sizes. Separate compiler experiments from distribution comparisons. Retain bounded independent minimality checks, negative tests, seeded property tests, source/patch mutations, coverage scopes, pinned acquisitions, reproduction commands and an offline HTML report without altering historical cohorts.\n","COMMENT":"DiffBench.cs; DiffModel.cs; DiffBench.Tests/ModelTests.cs; DiffBench.Tests/ReportTests.cs; DiffBench.Tests/stryker-config.json; scripts/Get-DiffTools.ps1; scripts/build-diff.sh; scripts/Run-DiffBench.ps1; results/diff/environment.json; results/diff/validation.json; results/diff/runs.jsonl; results/diff/summary.json; results/diff/report.html; results/diff/verification.json; results/diff/README.md. Git child-process memory/CPU were not measured: summary memory is null, and retained raw counters are explicitly launcher-only. Full third-party coverage and coverage-guided fuzzing remain unmeasured.","_LINK":"BENCH-012"}};
